import{a as e,i as t,r as n,t as r}from"./app-DllFuXBm.js";var i=JSON.parse(`{"path":"/guide/chu2.html","title":"中二节奏（CHUNITHM）","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1791220548000,"contributors":[{"name":"ShiroMizu","username":"","email":"ShiroMizuTan@163.com","commits":2}],"changelog":[{"hash":"04f74943892bd0445f091e844aa30b5a0db05484","time":1791220548000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add arcade forecast, character info ops and chu2 n20"},{"hash":"eb433ec98d8924e347272ad4868e5aebb7e1f1b1","time":1791134899000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add chunithm (maimai DX counterpart) page"}]},"filePathRelative":"guide/chu2.md"}`),a={name:`chu2.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="中二节奏-chunithm" tabindex="-1"><a class="header-anchor" href="#中二节奏-chunithm"><span>中二节奏（CHUNITHM）</span></a></h1><p>以下功能查询中二节奏的曲库、谱面和玩家成绩。所有指令都需要 <code>.</code> 前缀。</p><p>中二和舞萌是两套独立的数据，指令不通用，但<strong>共用同一份账号授权</strong> —— 见下方「账号绑定」。</p><h2 id="曲库与谱面" tabindex="-1"><a class="header-anchor" href="#曲库与谱面"><span>曲库与谱面</span></a></h2><table><thead><tr><th>指令 / 格式</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>查曲</code> / <code>中二查曲</code></td><td><code>曲名/别名/定数/曲师/谱师/分类 [页码]</code></td><td><code>.查曲 幾四音</code>、<code>.查曲 14.7</code></td><td>搜索歌曲；单曲发谱面信息卡，多曲发分页图片</td></tr><tr><td><code>中二id</code></td><td><code>曲目 ID</code></td><td><code>.中二id 8000</code></td><td>按曲目 ID 查谱面信息卡</td></tr></tbody></table><p>搜索时不需要指定搜什么，机器人会自动按这几个维度匹配：</p><table><thead><tr><th>输入</th><th>匹配什么</th></tr></thead><tbody><tr><td>曲名</td><td>精确匹配，匹配不上再退回到包含匹配</td></tr><tr><td>别名</td><td>同上</td></tr><tr><td>定数</td><td><code>14.7</code>（精确）或 <code>14</code>（该难度等级的全部谱面）</td></tr><tr><td>难度标级</td><td><code>14+</code> 这样的写法</td></tr><tr><td>曲师 / 分类</td><td>精确匹配</td></tr><tr><td>谱师</td><td>精确匹配</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>定数是<strong>精确匹配</strong>，没有「13 以上」这种范围搜索 —— 想找 13 以上的谱面，只能一个等级一个等级地查（<code>.查曲 13</code>、<code>.查曲 14</code>…）。</p></div><div class="hint-container tip"><p class="hint-container-title">提示</p><p>结果分三种情况：</p><ul><li><strong>只找到 1 首</strong> → 直接发谱面信息卡</li><li><strong>找到 2~5 首</strong> → 纯文本列出（比图片轻）</li><li><strong>找到更多</strong> → 发分页图片，每页 60 首，可在指令末尾加页码翻页（<code>.查曲 初音 2</code>）</li></ul><p>谱面信息卡会显示曲名、艺术家、分类、BPM、各难度定数、谱师、物量，以及<strong>你自己</strong>在这首曲上的成绩（如果查得到）。</p></div><div class="hint-container warning"><p class="hint-container-title">注意</p><p><strong>中二的别名库只覆盖约一半的曲子</strong>，而且没有第二个数据源能补齐。所以搜不到的时候，多半是别名没收录 —— 试试曲名原文，或者换个更短的关键词。</p><p>另外中二有 <strong>49 首曲子存在重名</strong>（原曲和它的 WORLD&#39;S END 版同名），所以搜到多首是正常情况，机器人不会替你随便挑一首，会把候选都列出来让你选。</p></div><h2 id="玩家成绩" tabindex="-1"><a class="header-anchor" href="#玩家成绩"><span>玩家成绩</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>中二b30</code> / <code>c30</code> / <code>C30</code></td><td>无</td><td><code>.c30</code></td><td>查询自己的 Rating 构成（Best 30 + 新曲 Best 20 两段一起出）</td></tr><tr><td><code>中二n20</code> / <code>n20</code> / <code>N20</code> / <code>c20</code></td><td>无</td><td><code>.n20</code></td><td>只看「新曲 Best 20」那一段</td></tr><tr><td><code>中二选择</code> / <code>中二selection</code> / <code>csel</code></td><td>无</td><td><code>.csel</code></td><td>查询 Selection 10</td></tr><tr><td><code>中二分数列表</code> / <code>cscore</code></td><td><code>[页码]</code></td><td><code>.cscore</code>、<code>.cscore 2</code></td><td>查询自己的全部成绩，可翻页</td></tr><tr><td><code>中二数据源</code></td><td><code>落雪</code> / <code>水鱼</code> / <code>自动</code></td><td><code>.中二数据源 落雪</code></td><td>设置自己的数据源偏好，只影响自己</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p><strong>中二的 RATING 由两段构成</strong>：</p><table><thead><tr><th>段</th><th>是什么</th></tr></thead><tbody><tr><td>Best 30</td><td>非当前版本谱面里RATING 最高的 30 首</td></tr><tr><td>新曲 Best 20</td><td>当前版本常规谱面里 RATING 最高的 20 首</td></tr></tbody></table><p>两段相加（最多 50 首）后取<strong>平均值</strong>得到总 RATING。所以 <code>.c30</code> 会把两段一起出， 只想看新曲那一段就用 <code>.n20</code>。WE 谱面不参与 RATING 计算。</p><p>段标题只给「段名 + 首数」，不堆中间计算值 —— 因为总 RATING 是平均值，不是把两段加起来。</p></div><div class="hint-container tip"><p class="hint-container-title">提示</p><p><strong>Selection 10</strong> 是 Best 30 以外、理论上还有机会进 b30 的那 10 首成绩，和上面两段是独立的东西。</p></div><p>不带参数执行 <code>.中二数据源</code> 会显示当前设置和曲库来源。</p><p>成绩查询默认「<strong>落雪优先</strong>」—— 中二玩家绝大多数在落雪，而且只有落雪那边有别名、物量、收藏品和曲绘。落雪查不到时会自动切到水鱼。想要固定用某一边就用 <code>.中二数据源</code> 改。</p><h2 id="账号绑定" tabindex="-1"><a class="header-anchor" href="#账号绑定"><span>账号绑定</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>绑定落雪</code> / <code>落雪绑定</code> / <code>bindlxns</code></td><td>无</td><td><code>.绑定落雪</code></td><td>生成落雪授权链接（权限：读取玩家数据）</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p><strong>中二没有单独的绑定指令。</strong> 落雪授权同时覆盖舞萌和中二，执行一次 <code>.绑定落雪</code>，<strong>两个游戏一起生效</strong>，不需要绑两遍。</p></div><p>绑定后先去 <a href="https://maimai.lxns.net/" target="_blank" rel="noopener noreferrer">落雪咖啡屋</a> 确认你的中二节奏数据已经同步过 —— 只在游戏里打了分但没同步，机器人这边是查不到的。</p><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题"><span>常见问题</span></a></h2><p><strong>Q：查不到我的成绩？</strong> 按顺序检查这几点：</p><ol><li>有没有执行过 <code>.绑定落雪</code>（未绑定时分数列表只显示完成标记，不显示分数）</li><li>有没有去落雪咖啡屋同步过中二数据</li><li>换个数据源试试：<code>.中二数据源 水鱼</code></li></ol><p><strong>Q：分数列表只显示打没打过，不显示分数？</strong> 说明还没绑定落雪。执行 <code>.绑定落雪</code> 就能看到分数和 RATING 了。</p><p><strong>Q：为什么会提示「请求过于频繁」？</strong> 查询太密集了，稍等一会儿再试。</p><p><strong>Q：提示「曲库数据尚未就绪」？</strong> 曲库正在同步或上次同步失败了，稍等再试。如果一直出现，请让机器人管理员检查。</p><h2 id="目前没有的功能" tabindex="-1"><a class="header-anchor" href="#目前没有的功能"><span>目前没有的功能</span></a></h2><p>以下功能因为上游接口限制暂时做不了，不是遗漏：</p><table><thead><tr><th>功能</th><th>原因</th></tr></thead><tbody><tr><td>Recent 50</td><td>上游对应接口已废弃</td></tr><tr><td>RATING 趋势图</td><td>上游未开放权限</td></tr><tr><td>成绩热力图</td><td>同上</td></tr><tr><td>定数完成表 / 难度进度表</td><td>上游没有按条件筛选的接口</td></tr><tr><td>收藏品（称号 / 名牌 / 头像）</td><td>中二的达成条件结构和舞萌完全不同，需要单独设计</td></tr></tbody></table>`,29)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};